#!/bin/sh
# Generated by installgen (https://github.com/lovrozagar/installgen). Regenerate it with `installgen build`.
#
#   curl -fsSL <url> | sh                  the latest version
#   curl -fsSL <url> | sh -s -- 1.2.3      a specific version
#
# Environment: @@ENV_PREFIX@@_VERSION, @@ENV_PREFIX@@_INSTALL_DIR, @@ENV_PREFIX@@_NO_MODIFY_PATH=1, NO_COLOR.
# POSIX sh: runs under dash, bash 3.2+, zsh and busybox ash. Everything runs in main, so a truncated download
# runs nothing.
set -u

setup_ui() {
	c_green=''
	c_yellow=''
	c_bold=''
	c_reset=''
	e_red=''
	e_yellow=''
	e_reset=''
	progress=0
	if [ -z "${NO_COLOR:-}" ]; then
		if [ -t 1 ]; then
			c_green=$(printf '\033[32m')
			c_yellow=$(printf '\033[33m')
			c_bold=$(printf '\033[1m')
			c_reset=$(printf '\033[0m')
		fi
		if [ -t 2 ]; then
			e_red=$(printf '\033[31m')
			e_yellow=$(printf '\033[33m')
			e_reset=$(printf '\033[0m')
			progress=1
		fi
	fi
	case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
	*UTF-8* | *utf-8* | *UTF8* | *utf8*)
		ok_glyph=$(printf '\342\234\223')
		down_glyph=$(printf '\342\206\223')
		;;
	*)
		ok_glyph='+'
		down_glyph='v'
		;;
	esac
}

row() {
	printf '%s%s%s %-10s %s\n' "$1" "$2" "$c_reset" "$3" "$4"
}

ok() {
	row "$c_green" "$ok_glyph" "$1" "$2"
}

warn_row() {
	row "$c_yellow" '!' "$1" "$2"
}

warn() {
	printf '%swarning:%s %s\n' "$e_yellow" "$e_reset" "$1" >&2
}

fail() {
	printf '%serror:%s %s\n' "$e_red" "$e_reset" "$1" >&2
	exit 1
}

need() {
	command -v "$1" >/dev/null 2>&1 || fail "$1 is required"
}

# `~` for paths under $HOME
display() {
	case "$1" in
	"$HOME"/*) printf '~%s' "${1#"$HOME"}" ;;
	*) printf '%s' "$1" ;;
	esac
}

fetch() {
	if [ "$downloader" = curl ]; then
		curl -fsSL @@CURL_FLAGS@@ --retry 3 -o "$2" "$1"
	elif [ "$wget_https" = 1 ]; then
		wget -q @@WGET_FLAGS@@ -O "$2" "$1"
	else
		wget -q -O "$2" "$1"
	fi
}

# The asset, with curl's progress bar on a terminal; the bar and its label are erased afterwards.
fetch_asset() {
	if [ "$downloader" = curl ] && [ "$progress" = 1 ]; then
		printf '%s %s\n' "$down_glyph" "$3" >&2
		curl -fL --progress-bar @@CURL_FLAGS@@ --retry 3 -o "$2" "$1" || return 1
		printf '\033[1A\033[2K\033[1A\033[2K' >&2
	else
		fetch "$1" "$2"
	fi
}

supported() {
	case " @@PLATFORMS@@ " in
	*" $1 "*) return 0 ;;
	esac
	return 1
}

# Sets asset_path, format, checksums_path and binary_in_archive from $version and $tag.
resolve_platform() {
	case "$1" in
@@PLATFORM_CASES@@
	*) return 1 ;;
	esac
}

sha256_of() {
	case "$hasher" in
	sha256sum) sha256sum "$1" | awk '{ print $1 }' ;;
	shasum) shasum -a 256 "$1" | awk '{ print $1 }' ;;
	*) openssl dgst -sha256 "$1" | awk '{ print $NF }' ;;
	esac
}

main() {
	setup_ui
	name=@@NAME@@
	base_url=@@BASE_URL@@
	latest_url=@@LATEST_URL@@
	default_version=@@DEFAULT_VERSION@@
	tag_prefix=@@TAG_PREFIX@@
	modify_path=@@MODIFY_PATH@@
	message=@@MESSAGE@@
	sh_url=@@SH_URL@@
	ps1_url=@@PS1_URL@@

	[ -n "${HOME:-}" ] || fail "HOME is not set"
	install_dir="${@@ENV_PREFIX@@_INSTALL_DIR:-}"
	if [ -n "$install_dir" ]; then
		dir_display=$(display "$install_dir")
	else
		install_dir=@@INSTALL_DIR@@
		dir_display=@@INSTALL_DIR_DISPLAY@@
	fi
	[ -z "${@@ENV_PREFIX@@_NO_MODIFY_PATH:-}" ] || modify_path=0
	requested="${1:-${@@ENV_PREFIX@@_VERSION:-}}"

	printf '%s%s installer%s\n' "$c_bold" "$name" "$c_reset"

	# Platform
	uname_s=$(uname -s 2>/dev/null) || uname_s=unknown
	uname_m=$(uname -m 2>/dev/null) || uname_m=unknown
	case "$uname_s" in
	Linux) os=linux ;;
	Darwin) os=darwin ;;
	MINGW* | MSYS* | CYGWIN*)
		[ -n "$ps1_url" ] || fail "no $name build for Windows"
		printf 'On Windows, install %s from PowerShell:\n  powershell -c "irm %s | iex"\n' "$name" "$ps1_url" >&2
		exit 1
		;;
	*) fail "unsupported OS: $uname_s" ;;
	esac
	case "$uname_m" in
	x86_64 | amd64) arch=amd64 ;;
	arm64 | aarch64 | armv8*) arch=arm64 ;;
	*) fail "unsupported architecture: $uname_m" ;;
	esac
	# An x86_64 shell under Rosetta still runs on Apple Silicon: prefer the native build.
	if [ "$os" = darwin ] && [ "$arch" = amd64 ] && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null)" = 1 ]; then
		arch=arm64
	fi
	if ! supported "$os/$arch"; then
		if [ "$os" = darwin ] && [ "$arch" = arm64 ] && supported darwin/amd64; then
			warn "no native Apple Silicon build of $name; installing the Intel build, which needs Rosetta 2"
			arch=amd64
		else
			fail "no $name build for $os/$arch"
		fi
	fi
	ok Detected "$os/$arch"

	# Preflight: every tool before the first download
	version=''
	tag=''
	resolve_platform "$os/$arch"
	if command -v curl >/dev/null 2>&1; then
		downloader=curl
	elif command -v wget >/dev/null 2>&1; then
		downloader=wget
	else
		fail "curl or wget is required"
	fi
	wget_https=0
	if [ "$downloader" = wget ] && [ -n "@@WGET_FLAGS@@" ] && wget --help 2>&1 | grep -q -e "@@WGET_FLAGS@@"; then
		wget_https=1
	fi
	need mktemp
	case "$format" in
	tar.gz)
		need tar
		need gzip
		;;
	zip)
		if command -v unzip >/dev/null 2>&1; then
			unzipper=unzip
		elif command -v busybox >/dev/null 2>&1 && busybox --list 2>/dev/null | grep -qx unzip; then
			unzipper=busybox
		elif command -v bsdtar >/dev/null 2>&1; then
			unzipper=bsdtar
		else
			fail "unzip is required (or busybox unzip, or bsdtar)"
		fi
		;;
	esac
	if [ -n "$checksums_path" ]; then
		if command -v sha256sum >/dev/null 2>&1; then
			hasher=sha256sum
		elif command -v shasum >/dev/null 2>&1; then
			hasher=shasum
		elif command -v openssl >/dev/null 2>&1; then
			hasher=openssl
		else
			fail "sha256sum, shasum or openssl is required to verify the download"
		fi
	fi

	tmp=$(mktemp -d 2>/dev/null || mktemp -d -t "$name") || fail "could not create a temporary directory"
	trap 'rm -rf "$tmp"' EXIT
	trap 'exit 130' INT TERM

	# Version: $1, then <PREFIX>_VERSION, then the baked default, then the latest file. v1.2.3 and 1.2.3 both work.
	version=$requested
	[ -n "$version" ] || version=$default_version
	from_latest=''
	if [ -z "$version" ] || [ "$version" = latest ]; then
		fetch "$latest_url" "$tmp/latest" || fail "could not resolve the latest version from $latest_url"
		version=$(cat "$tmp/latest")
		from_latest=' (latest)'
	fi
	version=$(printf '%s' "$version" | tr -d ' \t\r\n')
	version=${version#"$tag_prefix"}
	case "$version" in
	'' | *[!A-Za-z0-9._+-]*) fail "invalid version: '$version'" ;;
	esac
	tag="$tag_prefix$version"
	resolve_platform "$os/$arch"
	ok Version "$version$from_latest"

	# Download
	asset_url="$base_url/$asset_path"
	asset_file=${asset_path##*/}
	dl="$tmp/$asset_file"
	fetch_asset "$asset_url" "$dl" "$asset_file" || fail "download failed: $asset_url"
	ok Download "$asset_file"

	# Verify
	if [ -n "$checksums_path" ]; then
		checksums_url="$base_url/$checksums_path"
		fetch "$checksums_url" "$tmp/checksums" || fail "download failed: $checksums_url"
		# `hash  file`, `hash *file`, BSD `SHA256 (file) = hash`, or a file holding one bare hash
		expected=$(awk -v f="$asset_file" '
			$1 == "SHA256" && $2 == "(" f ")" && $3 == "=" { print $4; exit }
			NF >= 2 { n = $2; sub(/^\*/, "", n); if (n == f) { print $1; exit } }
		' "$tmp/checksums")
		if [ -z "$expected" ]; then
			expected=$(awk 'NF { c++; h = $1; w = NF } END { if (c == 1 && w == 1) print h }' "$tmp/checksums")
		fi
		[ -n "$expected" ] || fail "no checksum for $asset_file in $checksums_url"
		expected=$(printf '%s' "$expected" | tr 'A-F' 'a-f' | tr -d '\r')
		case "$expected" in
		*[!0-9a-f]*) fail "malformed checksum for $asset_file in $checksums_url" ;;
		esac
		[ "${#expected}" -eq 64 ] || fail "malformed checksum for $asset_file in $checksums_url"
		actual=$(sha256_of "$dl")
		[ "$actual" = "$expected" ] || fail "checksum mismatch for $asset_file: expected $expected, got $actual"
		ok Verified "sha256"
	else
		warn_row Verified "skipped: no checksums published"
	fi

	# Extract
	case "$format" in
	tar.gz)
		mkdir "$tmp/x" && gzip -dc "$dl" | tar -xf - -C "$tmp/x" || fail "could not extract $asset_file"
		;;
	zip)
		mkdir "$tmp/x" || fail "could not extract $asset_file"
		case "$unzipper" in
		unzip) unzip -q "$dl" -d "$tmp/x" ;;
		busybox) busybox unzip -q "$dl" -d "$tmp/x" ;;
		*) bsdtar -xf "$dl" -C "$tmp/x" ;;
		esac || fail "could not extract $asset_file"
		;;
	esac
	if [ "$format" = raw ]; then
		bin=$dl
	elif [ -n "$binary_in_archive" ]; then
		bin="$tmp/x/$binary_in_archive"
	else
		bin=$(find "$tmp/x" -type f -name "$name" | head -n 1)
	fi
	[ -n "$bin" ] && [ -f "$bin" ] || fail "$name not found in $asset_file"

	# Install: stage next to the target, then rename over it
	target="$install_dir/$name"
	if [ -e "$target" ]; then verb=Updated; else verb=Installed; fi
	mkdir -p "$install_dir" || fail "could not create $install_dir"
	stage="$install_dir/.$name.$$.tmp"
	if ! { cp "$bin" "$stage" && chmod 755 "$stage" && mv -f "$stage" "$target"; }; then
		rm -f "$stage"
		fail "could not install to $target"
	fi
	if [ "$os" = darwin ] && command -v xattr >/dev/null 2>&1; then
		xattr -d com.apple.quarantine "$target" >/dev/null 2>&1 || true
	fi
	target_display="$dir_display/$name"
	ok "$verb" "$target_display"

	# PATH
	found=$(command -v "$name" 2>/dev/null) || found=''
	if [ -n "$found" ] && [ "$found" != "$target" ]; then
		warn "$found comes first on PATH and shadows the new $name"
	fi
	now_line=''
	case ":$PATH:" in
	*":$install_dir:"*) on_path=1 ;;
	*) on_path=0 ;;
	esac
	if [ "$on_path" = 1 ]; then
		ok PATH "already set"
	elif [ "$modify_path" != 1 ]; then
		warn_row PATH "not changed; add $dir_display to PATH"
	else
		case "$install_dir" in
		*'"'* | *'$'* | *'`'* | *'\'*) unsafe=1 ;;
		*) unsafe=0 ;;
		esac
		case "$install_dir" in
		"$HOME"/*) path_expr="\$HOME${install_dir#"$HOME"}" ;;
		*) path_expr=$install_dir ;;
		esac
		profile_line="export PATH=\"$path_expr:\$PATH\""
		case "$(basename "${SHELL:-sh}")" in
		fish)
			profile="${XDG_CONFIG_HOME:-$HOME/.config}/fish/conf.d/$name.fish"
			profile_line="fish_add_path \"$path_expr\""
			;;
		zsh) profile="${ZDOTDIR:-$HOME}/.zshrc" ;;
		bash)
			if [ "$os" = darwin ]; then profile="$HOME/.bash_profile"; else profile="$HOME/.bashrc"; fi
			;;
		*) profile="$HOME/.profile" ;;
		esac
		if [ "$unsafe" = 1 ]; then
			warn_row PATH "not changed: $install_dir has characters a profile line cannot hold; add it by hand"
		elif [ -f "$profile" ] && grep -qxF "$profile_line" "$profile"; then
			ok PATH "already in $(display "$profile")"
			now_line=$profile_line
		elif mkdir -p "$(dirname "$profile")" && printf '\n# %s\n%s\n' "$name" "$profile_line" >>"$profile"; then
			ok PATH "added to $(display "$profile")"
			now_line=$profile_line
		else
			warn_row PATH "could not write $(display "$profile"); add $dir_display to PATH"
		fi
		if [ -n "${GITHUB_PATH:-}" ]; then
			printf '%s\n' "$install_dir" >>"$GITHUB_PATH" || warn "could not append to \$GITHUB_PATH"
		fi
	fi

	if [ "$verb" = Updated ]; then done_word=updated; else done_word=installed; fi
	printf '\n%s%s %s %s.%s\n' "$c_bold" "$name" "$version" "$done_word" "$c_reset"
	[ -z "$message" ] || printf '%s\n' "$message"
	[ -z "$now_line" ] || printf 'Restart your shell, or run: %s\n' "$now_line"
	printf 'To uninstall: rm %s\n' "$target_display"
	printf 'To update: curl -fsSL %s | sh\n' "$sh_url"
}

main "$@"
